use vstd::prelude::*;

verus! {
    // A specification: for a sequence `seq` of length `len`,
    // every even index < len has an even element.
    spec fn even_idx_even_prefix(seq: Seq<i32>, len: nat) -> bool {
        forall |j: nat|
            j < len ==>
                (j % 2 != 0) || (seq[j] % 2 == 0)
    }

    // The implementation checks each position in turn,
    // maintaining the prefix property in the loop invariant.
    fn is_even_at_index_even(lst: &Vec<i32>) -> (result: bool)
        ensures
            // At the end, `result` holds exactly the property
            // that every even index < lst.len() has an even element.
            result == even_idx_even_prefix(lst@, lst.len())
    {
        let n: usize = lst.len();
        let mut i: usize = 0;
        let mut ok: bool = true;
        while i < n
            invariant
                // `i` stays within bounds
                i <= n,
                // `ok` records the fact that the prefix [0..i) satisfies the property
                ok == even_idx_even_prefix(lst@, i),
            decreases n - i,
        {
            // compute whether the new position `i` satisfies the property
            let cond: bool = if i % 2 == 0 {
                lst[i] % 2 == 0
            } else {
                true
            };
            // combine with the old prefix fact
            ok = ok && cond;
            i = i + 1;
        }
        ok
    }
}

fn main() {
    // Example usage (not part of the verification):
    let v = Vec::from(vec![2, 3, 4, 5, 6]);
    assert!(is_even_at_index_even(&v)); // true, since positions 0,2,4 are 2,4,6
    let w = Vec::from(vec![2, 3, 5, 5]);
    assert!(!is_even_at_index_even(&w)); // false, since position 2 has 5 (odd)
}